# Role
Your goal is to produce an optimized version of the given C code.

# System Information
Consider a sufficiently modern x64 Linux machine with 32 physical cores (64 hyperthreads) with the GCC 15.2.0 compiler installed. The code will be compiled with `-O3 -DNDEBUG` flags and the 23 version of the language standard.

# Optimization Guidelines
When optimizing C code, adhere to the following guidelines:

1. Preserve the original include directives and add any necessary headers for optimization techniques used.

2. Ensure all loop transformations and optimizations preserve the original computation semantics. The provided dimensions may not be divisible by common tiling factors; handle edge cases appropriately.

The resulting code must be valid, compilable C code.

# Task
Carefully examine the code and produce an optimized version focusing on improving data locality, computational efficiency, and memory access patterns while preserving the original functionality of the code. Keep the boilerplate code used for setting up the data structures and measuring execution time intact. The resulting code must be a valid C program without any omissions, and it must preserve the original boilerplate code used for setting up the data structures and measuring execution time.

# Verbosity and Reasoning
Write code that you are confident preserves the original functionality while optimizing performance. Before outputting the final code, double-check its semantics against the original code and iteratively refine the draft until it meets the expected functionality and optimization goals. The resulting code should be well-commented and explicit. Any unobvious optimization techniques should be accompanied by comments that clearly explain their semantics and purpose. Interpretability of the resulting code is essential.

# Model Translation Guidelines

Given a C code snippet:

```c
/**
 * This version is stamped on May 10, 2016
 *
 * Contact:
 *   Louis-Noel Pouchet <pouchet.ohio-state.edu>
 *   Tomofumi Yuki <tomofumi.yuki.fr>
 *
 * Web address: http://polybench.sourceforge.net
 */
/* gemm.c: this file is part of PolyBench/C */

#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "gemm.h"


/* Array initialization. */
static
void init_array(int ni, int nj, int nk,
		DATA_TYPE *alpha,
		DATA_TYPE *beta,
		DATA_TYPE POLYBENCH_2D(C,NI,NJ,ni,nj),
		DATA_TYPE POLYBENCH_2D(A,NI,NK,ni,nk),
		DATA_TYPE POLYBENCH_2D(B,NK,NJ,nk,nj))
{
  int i, j;

  *alpha = 1.5;
  *beta = 1.2;
  for (i = 0; i < ni; i++)
    for (j = 0; j < nj; j++)
      C[i][j] = (DATA_TYPE) ((i*j+1) % ni) / ni;
  for (i = 0; i < ni; i++)
    for (j = 0; j < nk; j++)
      A[i][j] = (DATA_TYPE) (i*(j+1) % nk) / nk;
  for (i = 0; i < nk; i++)
    for (j = 0; j < nj; j++)
      B[i][j] = (DATA_TYPE) (i*(j+2) % nj) / nj;
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int ni, int nj,
		 DATA_TYPE POLYBENCH_2D(C,NI,NJ,ni,nj))
{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("C");
  for (i = 0; i < ni; i++)
    for (j = 0; j < nj; j++) {
	if ((i * ni + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
	fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, C[i][j]);
    }
  POLYBENCH_DUMP_END("C");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_gemm[[gnu::flatten, gnu::noinline]](int ni, int nj, int nk,
		 DATA_TYPE alpha,
		 DATA_TYPE beta,
		 DATA_TYPE POLYBENCH_2D(C,NI,NJ,ni,nj),
		 DATA_TYPE POLYBENCH_2D(A,NI,NK,ni,nk),
		 DATA_TYPE POLYBENCH_2D(B,NK,NJ,nk,nj))
{
  int i, j, k;

//BLAS PARAMS
//TRANSA = 'N'
//TRANSB = 'N'
// => Form C := alpha*A*B + beta*C,
//A is NIxNK
//B is NKxNJ
//C is NIxNJ
#pragma scop
  for (i = 0; i < _PB_NI; i++) {
    for (j = 0; j < _PB_NJ; j++)
	C[i][j] *= beta;
    for (k = 0; k < _PB_NK; k++) {
       for (j = 0; j < _PB_NJ; j++)
	  C[i][j] += alpha * A[i][k] * B[k][j];
    }
  }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int ni = NI;
  int nj = NJ;
  int nk = NK;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  DATA_TYPE beta;
  POLYBENCH_2D_ARRAY_DECL(C,DATA_TYPE,NI,NJ,ni,nj);
  POLYBENCH_2D_ARRAY_DECL(A,DATA_TYPE,NI,NK,ni,nk);
  POLYBENCH_2D_ARRAY_DECL(B,DATA_TYPE,NK,NJ,nk,nj);

  /* Initialize array(s). */
  init_array (ni, nj, nk, &alpha, &beta,
	      POLYBENCH_ARRAY(C),
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(B));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_gemm (ni, nj, nk,
	       alpha, beta,
	       POLYBENCH_ARRAY(C),
	       POLYBENCH_ARRAY(A),
	       POLYBENCH_ARRAY(B));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(ni, nj,  POLYBENCH_ARRAY(C)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(C);
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(B);

  return 0;
}
```

With an unoptimized model description:

```
domain:
    i: dim in [0, NI)
    j: dim in [0, NJ)
    k: dim in [0, NK)
data:
    A[i, k]: in DATA_TYPE = (i, k) -> i * NK + k  # Row-major
    B[k, j]: in DATA_TYPE = (k, j) -> k * NJ + j  # Row-major
    C[i, j]: inout DATA_TYPE = (i, j) -> i * NJ + j  # Row-major
parameters:
    alpha: DATA_TYPE
    beta: DATA_TYPE
computation:
    for i, j:
        C[i, j] = beta * C[i, j] + alpha * sum(k, A[i, k] * B[k, j])
```

And an optimized model description:

```
domain:
    i: dim in [0, NI)
    j: dim in [0, NJ)
    k: dim in [0, NK)
data:
    A[i, k]: in DATA_TYPE = (i, k) -> i * NK + k  # Row-major
    B[k, j]: in DATA_TYPE = (k, j) -> j * NK + k  # Column-major
    C[i, j]: inout DATA_TYPE = (i, j) -> i * NJ + j  # Row-major
parameters:
    alpha: DATA_TYPE
    beta: DATA_TYPE
computation:
    for i, j:
        C[i, j] = beta * C[i, j] + alpha * sum(k, A[i, k] * B[k, j])
optimization:
    block(i, I, 16)
    block(j, J, 16)
    block(k, K, 16)
    hoist(I)
    hoist(J)
    hoist(K)
```

