    y1[i, j]: temp DATA_TYPE     = (i, j) -> i * H + j  # temporary for forward passes
    y2[i, j]: temp DATA_TYPE     = (i, j) -> i * H + j  # temporary for backward passes

parameters:
    alpha: DATA_TYPE   # filter parameter in (0, 1], set to 0.25 in this benchmark

    # Filter coefficients (same as in the C code, computed once per kernel call)
    k:  DATA_TYPE
    a1: DATA_TYPE  # horizontal/vertical forward
    a2: DATA_TYPE
    a3: DATA_TYPE  # horizontal/vertical backward
    a4: DATA_TYPE
    a5: DATA_TYPE  # equal to a1
    a6: DATA_TYPE  # equal to a2
    a7: DATA_TYPE  # equal to a3
    a8: DATA_TYPE  # equal to a4
    b1: DATA_TYPE
    b2: DATA_TYPE
    c1: DATA_TYPE  # horizontal combination gain
    c2: DATA_TYPE  # vertical combination gain

    # Tunable integer parameters for optimization (chosen based on hardware)
    TI: int  # tile size in i (rows), e.g., 64
    TJ: int  # tile size in j (cols), e.g., 64
    VEC: int # SIMD width for vectorization, e.g., 4 or 8

computation:
    # Coefficient setup: identical algebra to the C code
    COEFFS:
        let e1  = EXP(-alpha)
        let e2  = EXP(-2 * alpha)
        let pow2 = POW(2.0, -alpha)

        k  = (1.0 - e1) * (1.0 - e1) /
             (1.0 + 2.0 * alpha * e1 - EXP(2.0 * alpha))
        a1 = k
        a2 = k * e1 * (alpha - 1.0)
        a3 = k * e1 * (alpha + 1.0)
        a4 = -k * e2
        a5 = a1
        a6 = a2
        a7 = a3
        a8 = a4
        b1 = pow2
        b2 = -e2
        c1 = 1.0
        c2 = 1.0

    #--------------------------------------------------
    # 1) Horizontal pass: forward (causal) recursion
    #    y1[i, j] depends on imgIn[i, j], imgIn[i, j-1], y1[i, j-1], y1[i, j-2]
    #    with zero-border initial conditions in j.
    #--------------------------------------------------
    H_fwd:
        for i in [0, W):
            for j in seq([0, H)):  # strictly left-to-right along each row
                y1[i, j] =
                    a1 * imgIn[i, j] +
                    a2 * (if j > 0 then imgIn[i, j-1] else 0.0) +
                    b1 * (if j > 0 then y1[i, j-1] else 0.0) +
                    b2 * (if j > 1 then y1[i, j-2] else 0.0)

    #--------------------------------------------------
    # 2) Horizontal pass: backward (anti-causal) recursion
    #    y2[i, j] depends on imgIn[i, j+1], imgIn[i, j+2], y2[i, j+1], y2[i, j+2]
    #    with zero-border conditions at the right edge (j = H, H+1 treated as 0).
    #--------------------------------------------------
    H_bwd:
        for i in [0, W):
            for j in seq([H-1, -1]):  # j = H-1, H-2, ..., 0
                y2[i, j] =
                    a3 * (if j + 1 < H then imgIn[i, j+1] else 0.0) +
                    a4 * (if j + 2 < H then imgIn[i, j+2] else 0.0) +
                    b1 * (if j + 1 < H then y2[i, j+1] else 0.0) +
                    b2 * (if j + 2 < H then y2[i, j+2] else 0.0)

    #--------------------------------------------------
    # 3) Horizontal combination:
    #    imgOut = c1 * (y1 + y2)
    #    (this is the horizontally filtered image used as input to the vertical pass)
    #--------------------------------------------------
    H_combine:
        for i, j:
            imgOut[i, j] = c1 * (y1[i, j] + y2[i, j])

    #--------------------------------------------------
    # 4) Vertical pass: forward (causal) recursion
    #    Now operate down each column of imgOut, reusing y1 as temp storage.
    #    y1[i, j] depends on imgOut[i, j], imgOut[i-1, j], y1[i-1, j], y1[i-2, j]
    #    with zero-border conditions at i = -1, -2.
    #--------------------------------------------------
    V_fwd:
        for j in [0, H):
            for i in seq([0, W)):  # top-to-bottom along each column
                y1[i, j] =
                    a5 * imgOut[i, j] +
                    a6 * (if i > 0 then imgOut[i-1, j] else 0.0) +
                    b1 * (if i > 0 then y1[i-1, j] else 0.0) +
                    b2 * (if i > 1 then y1[i-2, j] else 0.0)

    #--------------------------------------------------
    # 5) Vertical pass: backward (anti-causal) recursion
    #    y2[i, j] depends on imgOut[i+1, j], imgOut[i+2, j], y2[i+1, j], y2[i+2, j]
    #    with zero-border conditions at the bottom (i = W, W+1 treated as 0).
    #--------------------------------------------------
    V_bwd:
        for j in [0, H):
            for i in seq([W-1, -1]):  # i = W-1, W-2, ..., 0
                y2[i, j] =
                    a7 * (if i + 1 < W then imgOut[i+1, j] else 0.0) +
                    a8 * (if i + 2 < W then imgOut[i+2, j] else 0.0) +
                    b1 * (if i + 1 < W then y2[i+1, j] else 0.0) +
                    b2 * (if i + 2 < W then y2[i+2, j] else 0.0)

    #--------------------------------------------------
    # 6) Vertical combination:
    #    final output: imgOut = c2 * (y1 + y2)
    #--------------------------------------------------
    V_combine:
        for i, j:
            imgOut[i, j] = c2 * (y1[i, j] + y2[i, j])

dependencies:
    # Horizontal forward: y1[i, j] depends on previous two samples along j for fixed i.
    for i in [0, W), j in [0, H):
        if j > 0: H_fwd(i, j-1) -> H_fwd(i, j)
        if j > 1: H_fwd(i, j-2) -> H_fwd(i, j)

    # Horizontal backward: y2[i, j] depends on y2[i, j+1], y2[i, j+2].
    for i in [0, W), j in [0, H):
        if j + 1 < H: H_bwd(i, j+1) -> H_bwd(i, j)
        if j + 2 < H: H_bwd(i, j+2) -> H_bwd(i, j)

    # Horizontal combination uses fully computed y1 and y2.
    for i, j:
        H_fwd(i, j) -> H_combine(i, j)
        H_bwd(i, j) -> H_combine(i, j)

    # Vertical forward: y1[i, j] depends on y1[i-1, j], y1[i-2, j].
    for j in [0, H), i in [0, W):
        if i > 0: V_fwd(i-1, j) -> V_fwd(i, j)
        if i > 1: V_fwd(i-2, j) -> V_fwd(i, j)

    # Vertical backward: y2[i, j] depends on y2[i+1, j], y2[i+2, j].
    for j in [0, H), i in [0, W):
        if i + 1 < W: V_bwd(i+1, j) -> V_bwd(i, j)
        if i + 2 < W: V_bwd(i+2, j) -> V_bwd(i, j)

    # Vertical combination uses fully computed vertical y1 and y2.
    for i, j:
        V_fwd(i, j) -> V_combine(i, j)
        V_bwd(i, j) -> V_combine(i, j)

optimization:
    #--------------------------------------------------
    # Parallelism
    #--------------------------------------------------
    # Rows are independent for all horizontal phases:
    #   - each H_fwd(i, *) and H_bwd(i, *) only use data from row i
    #   - H_combine is pointwise
    # So we safely parallelize over i in those stages.
    parallelize(i)  # applied to H_fwd, H_bwd, H_combine

    # Columns are independent for all vertical phases:
    #   - each V_fwd(*, j) and V_bwd(*, j) only use data from column j
    #   - V_combine is pointwise
    # So we safely parallelize over j there.
    parallelize(j)  # applied to V_fwd, V_bwd, V_combine

    #--------------------------------------------------
    # Cache tiling (blocking)
    #--------------------------------------------------
    # Tile both dimensions so that a TI x TJ block fits comfortably in L1/L2.
    # This improves locality for imgIn, imgOut, y1, and y2, and is especially
    # beneficial when W and H are large.
    block(i, I, TI)
    block(j, J, TJ)

    # The tiling preserves the 1D recurrences because tiles are visited in
    # lexicographic order and the inner "seq" iteration along the recurrence
    # dimension (j for horizontal, i for vertical) is not reordered within a tile.

    #--------------------------------------------------
    # Loop fusion for temporal locality
    #--------------------------------------------------
    # Fuse the three horizontal phases by row:
    #   for each i:
    #      run H_fwd(i, *), then H_bwd(i, *), then H_combine(i, *)
    # This keeps row i of y1, y2, imgIn, and imgOut hot in cache.
    # Similarly, fuse vertical phases by column.
    #
    # We introduce a custom directive to express this:
    #   fuse_rows(H_fwd, H_bwd, H_combine)
    #   fuse_cols(V_fwd, V_bwd, V_combine)
    # which groups the three stages under a single outer loop over i (rows)
    # and j (columns), respectively, without violating the dependencies.
    fuse_rows(H_fwd, H_bwd, H_combine)
    fuse_cols(V_fwd, V_bwd, V_combine)

    #--------------------------------------------------
    # Vectorization and unrolling
    #--------------------------------------------------
    # The recurrence prevents straightforward SIMD along the recurrence
    # dimension, but elementwise combination loops are fully independent.
    # Vectorize those over the innermost dimension j.
    vectorize(j, VEC)  # applied to H_combine and V_combine

    # For the sequential recurrence loops, unrolling by a small factor
    # reduces loop overhead and exposes more ILP to the compiler.
    unroll(j, 4)  # inner j loops in H_fwd and H_bwd
    unroll(i, 4)  # inner i loops in V_fwd and V_bwd

    #--------------------------------------------------
    # Scalar-expression optimizations
    #--------------------------------------------------
    # The coefficient computation already hoists all expensive transcendental
    # calls (EXP, POW) out of the image loops. To further reduce arithmetic:
    #
    # - Common subexpressions like k * e1 are computed once:
    #     let ke1 = k * e1
    #     a2 = ke1 * (alpha - 1.0)
    #     a3 = ke1 * (alpha + 1.0)
    #
    # - The gains c1 and c2 are known to be 1.0 in this benchmark; multiplications
    #   by them can be eliminated, turning both combinations into:
    #     imgOut[i, j] = y1[i, j] + y2[i, j]
    #
    # A compiler with -O3 will typically perform these automatically, but they
    # are explicitly allowed and do not change program semantics.
--- END OF MODEL: deriche-01 ---

--- START OF MODEL: deriche-02 ---
# Optimized model for deriche.c
#
# Additional iteration constructs used:
#   - seq([L, U)):        ordered traversal from L to U-1 (as in a standard for-loop).
#   - seq_reverse([L, U)): ordered traversal from U-1 down to L.
#
# These express loop-carried dependencies (IIR recurrences) along one dimension.

domain:
    i: dim in [0, W)   # image width  (rows)
    j: dim in [0, H)   # image height (columns)

data:
    # 2D images are stored row-major: index(i, j) = i * H + j

    imgIn[i, j]:  in    DATA_TYPE = (i, j) -> i * H + j  # original input image
    imgOut[i, j]: inout DATA_TYPE = (i, j) -> i * H + j  # horizontal-then-vertical filtered image

    # Temporary buffers for intermediate recursive results (same as C code y1, y2).
    y1[i, j]: temp DATA_TYPE = (i, j) -> i * H + j      # used for causal passes
    y2[i, j]: temp DATA_TYPE = (i, j) -> i * H + j      # used for anti-causal passes

parameters:
    # Algorithm parameter
    alpha: DATA_TYPE

    # Tunable integer parameters (chosen experimentally per machine)
    T_I: int    # tile size along i (rows), e.g., 32–128
    T_J: int    # tile size along j (cols), e.g., 32–128
    VEC_WIDTH: int  # SIMD width along contiguous j dimension
    UNROLL_J: int   # unroll factor for combination loops along j (e.g., 4 or 8)
    UF_H: int       # small unroll factor for horizontal recurrences (e.g., 2)
    UF_V: int       # small unroll factor for vertical recurrences (e.g., 2)

computation:
    # -------------------------------------------------------------------------
    # 0. Precompute scalar constants from alpha (hoisted out of image loops)
    #    This avoids redundant transcendental calls in every iteration.
    # -------------------------------------------------------------------------
    CONSTS:
        emA   = exp(-alpha)                     # e^{-alpha}
        em2A  = emA * emA                       # e^{-2 alpha}
        k     = (1 - emA) * (1 - emA) /
                (1 + 2 * alpha * emA - em2A)
        a1    = k
        a2    = k * emA * (alpha - 1)
        a3    = k * emA * (alpha + 1)
        a4    = -k * em2A
        a5    = a1
        a6    = a2
        a7    = a3
        a8    = a4
        b1    = pow(2, -alpha)                  # can be implemented as exp2(-alpha)
        b2    = -em2A
        c1    = 1
        c2    = 1

    # -------------------------------------------------------------------------
    # 1. Horizontal pass (left-right + right-left) on imgIn -> y1, y2
    #    These are 1D IIR filters applied independently to each row.
    #    Dependencies are along j only; rows (i) are independent.
    # -------------------------------------------------------------------------

    # 1a. Horizontal causal recursion (left-to-right)
    #      y1[i, j] depends on imgIn[i, j], imgIn[i, j-1], y1[i, j-1], y1[i, j-2]
    HORIZ_CAUSAL:
        for i in [0, W):
            # j must be sequential because of IIR dependence along the row.
            for j in seq([0, H)):
                if j == 0:
                    # xm1 = 0, ym1 = 0, ym2 = 0
                    y1[i, j] = a1 * imgIn[i, j]
                elif j == 1:
                    # xm1 = imgIn[i, 0], ym1 = y1[i, 0], ym2 = 0
                    y1[i, j] = a1 * imgIn[i, j] +
                               a2 * imgIn[i, j - 1] +
                               b1 * y1[i, j - 1]
                else:
                    # xm1 = imgIn[i, j-1], ym1 = y1[i, j-1], ym2 = y1[i, j-2]
                    y1[i, j] = a1 * imgIn[i, j] +
                               a2 * imgIn[i, j - 1] +
                               b1 * y1[i, j - 1] +
                               b2 * y1[i, j - 2]

    # 1b. Horizontal anti-causal recursion (right-to-left)
    #      y2[i, j] depends on imgIn[i, j+1], imgIn[i, j+2], y2[i, j+1], y2[i, j+2]
    HORIZ_ANTICAUSAL:
        for i in [0, W):
            # reverse-ordered j loop expresses xp1/xp2, yp1/yp2 recurrences.
            for j in seq_reverse([0, H)):  # j = H-1, H-2, ..., 0
                if j == H - 1:
                    # xp1 = xp2 = yp1 = yp2 = 0
                    y2[i, j] = 0
                elif j == H - 2:
                    # xp1 = imgIn[i, H-1], xp2 = 0,
                    # yp1 = y2[i, H-1], yp2 = 0
                    y2[i, j] = a3 * imgIn[i, j + 1] +
                               b1 * y2[i, j + 1]
                else:
                    # xp1 = imgIn[i, j+1], xp2 = imgIn[i, j+2],
                    # yp1 = y2[i, j+1], yp2 = y2[i, j+2]
                    y2[i, j] = a3 * imgIn[i, j + 1] +
                               a4 * imgIn[i, j + 2] +
                               b1 * y2[i, j + 1] +
                               b2 * y2[i, j + 2]

    # 1c. Horizontal combination: form horizontally filtered image
    #      imgOut[i, j] = c1 * (y1[i, j] + y2[i, j])
    HORIZ_COMBINE:
        for i in [0, W):
            for j in [0, H):
                imgOut[i, j] = c1 * (y1[i, j] + y2[i, j])

    # -------------------------------------------------------------------------
    # 2. Vertical pass (top-bottom + bottom-top) on imgOut -> y1, y2
    #    These are 1D IIR filters applied independently to each column.
    #    Dependencies are along i only; columns (j) are independent.
    # -------------------------------------------------------------------------

    # 2a. Vertical causal recursion (top-to-bottom)
    #      y1[i, j] depends on imgOut[i, j], imgOut[i-1, j],
    #                      y1[i-1, j], y1[i-2, j]
    VERT_CAUSAL:
        for j in [0, H):
            # i must be sequential because of IIR dependence along the column.
            for i in seq([0, W)):
                if i == 0:
                    # tm1 = 0, ym1 = 0, ym2 = 0
                    y1[i, j] = a5 * imgOut[i, j]
                elif i == 1:
                    # tm1 = imgOut[0, j], ym1 = y1[0, j], ym2 = 0
                    y1[i, j] = a5 * imgOut[i, j] +
                               a6 * imgOut[i - 1, j] +
                               b1 * y1[i - 1, j]
                else:
                    # tm1 = imgOut[i-1, j], ym1 = y1[i-1, j], ym2 = y1[i-2, j]
                    y1[i, j] = a5 * imgOut[i, j] +
                               a6 * imgOut[i - 1, j] +
                               b1 * y1[i - 1, j] +
                               b2 * y1[i - 2, j]

    # 2b. Vertical anti-causal recursion (bottom-to-top)
    #      y2[i, j] depends on imgOut[i+1, j], imgOut[i+2, j],
    #                      y2[i+1, j], y2[i+2, j]
    VERT_ANTICAUSAL:
        for j in [0, H):
            for i in seq_reverse([0, W)):  # i = W-1, W-2, ..., 0
                if i == W - 1:
                    # tp1 = tp2 = yp1 = yp2 = 0
                    y2[i, j] = 0
                elif i == W - 2:
                    # tp1 = imgOut[W-1, j], tp2 = 0,
                    # yp1 = y2[W-1, j],     yp2 = 0
                    y2[i, j] = a7 * imgOut[i + 1, j] +
                               b1 * y2[i + 1, j]
                else:
                    # tp1 = imgOut[i+1, j], tp2 = imgOut[i+2, j],
                    # yp1 = y2[i+1, j],     yp2 = y2[i+2, j]
                    y2[i, j] = a7 * imgOut[i + 1, j] +
                               a8 * imgOut[i + 2, j] +
                               b1 * y2[i + 1, j] +
                               b2 * y2[i + 2, j]

    # 2c. Vertical combination: final output
    #      imgOut[i, j] = c2 * (y1[i, j] + y2[i, j])
    VERT_COMBINE:
        for i in [0, W):
            for j in [0, H):
                imgOut[i, j] = c2 * (y1[i, j] + y2[i, j])


dependencies:
    # Phase ordering across the whole image:
    #   CONSTS -> HORIZ_CAUSAL/HORIZ_ANTICAUSAL -> HORIZ_COMBINE
    #           -> VERT_CAUSAL/VERT_ANTICAUSAL -> VERT_COMBINE

    for i in [0, W), j in [0, H):
        CONSTS        -> HORIZ_CAUSAL(i, j)
        CONSTS        -> HORIZ_ANTICAUSAL(i, j)

        HORIZ_CAUSAL(i, j)     -> HORIZ_COMBINE(i, j)
        HORIZ_ANTICAUSAL(i, j) -> HORIZ_COMBINE(i, j)

        HORIZ_COMBINE(i, j) -> VERT_CAUSAL(i, j)
        HORIZ_COMBINE(i, j) -> VERT_ANTICAUSAL(i, j)

        VERT_CAUSAL(i, j)     -> VERT_COMBINE(i, j)
        VERT_ANTICAUSAL(i, j) -> VERT_COMBINE(i, j)

    # Intra-row / intra-column recurrences are already captured by seq / seq_reverse
    # and do not need to be restated here.


optimization:
    # -------------------------------------------------------------------------
    # Constant hoisting
    # -------------------------------------------------------------------------
    # All scalar constants emA, em2A, k, a1..a8, b1, b2, c1, c2 are loop-invariant.
    # Ensure they are computed once and kept in registers across all loops.
    hoist(emA)
    hoist(em2A)
    hoist(k)
    hoist(a1); hoist(a2); hoist(a3); hoist(a4)
    hoist(a5); hoist(a6); hoist(a7); hoist(a8)
    hoist(b1); hoist(b2)
    hoist(c1); hoist(c2)

    # -------------------------------------------------------------------------
    # Parallelization
    # -------------------------------------------------------------------------
    # Rows are independent in the horizontal phase; columns are independent in
    # the vertical phase. We exploit outer-loop parallelism at tile granularity.
    #
    # On a 32-core (64-thread) machine, choose tile sizes T_I, T_J so that
    # the number of tiles is at least as large as the number of hardware threads.
    #
    # Horizontal phase: parallelize across rows i (and row tiles I_tile).
    block(i, I_tile, T_I)      # introduce outer tile index I_tile and inner i
    parallelize(I_tile)        # distribute row tiles across threads (HORIZ_*)

    # Vertical phase: parallelize across columns j (and column tiles J_tile).
    block(j, J_tile, T_J)      # introduce outer tile index J_tile and inner j
    parallelize(J_tile)        # distribute column tiles across threads (VERT_*)

    # Note: dimensions marked seq / seq_reverse (j in HORIZ_*, i in VERT_*)
    # remain strictly sequential within each tile, preserving IIR recurrences.

    # -------------------------------------------------------------------------
    # Vectorization and unrolling
    # -------------------------------------------------------------------------
    # Only pointwise combination loops (no recurrences) are safe to vectorize.
    # In row-major layout, j is contiguous in memory, so vectorize along j.
    vectorize(j, VEC_WIDTH)    # apply to HORIZ_COMBINE and VERT_COMBINE
    unroll(j, UNROLL_J)        # unroll those same combination loops to increase ILP

    # Recurrence loops cannot be vectorized along the dependence dimension,
    # but modest unrolling can still increase ILP while preserving semantics.

    # Horizontal recurrences along j:
    unroll(j, UF_H)            # apply to j in HORIZ_CAUSAL and HORIZ_ANTICAUSAL

    # Vertical recurrences along i:
    unroll(i, UF_V)            # apply to i in VERT_CAUSAL and VERT_ANTICAUSAL

    # -------------------------------------------------------------------------
    # Memory locality and cache behavior
    # -------------------------------------------------------------------------
    # - Row-major layout makes j-contiguous accesses cache-friendly.
    #   Horizontal passes (HORIZ_*) and combination loops benefit from this.
    # - Vertical passes (VERT_*) inherently access imgOut with stride H.
    #
    # To improve L2/L3 locality and NUMA behavior without extra 2D buffers:
    #
    #   * Use the same tiling (block(j, J_tile, T_J)) for VERT_CAUSAL and
    #     VERT_ANTICAUSAL so that both passes reuse the same column tiles
    #     while they remain hot in cache.
    #
    #   * Choose T_I, T_J such that tiles fit comfortably in L2 cache, taking
    #     into account that four 2D arrays (imgIn, imgOut, y1, y2) of a tile
    #     may be active at once.
    #
    # Extra memory usage remains identical to the original program (imgIn,
    # imgOut, y1, y2 only), satisfying the memory footprint constraint.
--- END OF MODEL: deriche-02 ---

--- START OF MODEL: deriche-03 ---
domain:
    i: dim in [0, W)   # image width  (PolyBench macro W)
    j: dim in [0, H)   # image height (PolyBench macro H)

data:
    # 2D images, row-major layout as in the C code: img[x][y] -> x * H + y
    imgIn[i, j]:  in    DATA_TYPE = (i, j) -> i * H + j
    imgOut[i, j]: inout DATA_TYPE = (i, j) -> i * H + j

    # Temporary images used for the recursive Deriche filter
    y1[i, j]: tmp DATA_TYPE = (i, j) -> i * H + j
    y2[i, j]: tmp DATA_TYPE = (i, j) -> i * H + j

    # Scalar filter coefficients (loop-invariant, computed from alpha)
    e1: tmp DATA_TYPE
    e2: tmp DATA_TYPE
    k:  tmp DATA_TYPE
    a1: tmp DATA_TYPE
    a2: tmp DATA_TYPE
    a3: tmp DATA_TYPE
    a4: tmp DATA_TYPE
    a5: tmp DATA_TYPE
    a6: tmp DATA_TYPE
    a7: tmp DATA_TYPE
    a8: tmp DATA_TYPE
    b1: tmp DATA_TYPE
    b2: tmp DATA_TYPE
    c1: tmp DATA_TYPE
    c2: tmp DATA_TYPE

parameters:
    alpha:      DATA_TYPE   # filter parameter
    TILE_W:     int         # tunable tile size along i (e.g., 32–256)
    TILE_H:     int         # tunable tile size along j (e.g., 32–256)
    VF:         int         # SIMD vector width for vectorized loops
    NUM_THREADS: int        # number of worker threads for parallel execution

computation:

    COEFFS:
        # Same coefficient formulas as in the original kernel
        e1 = EXP_FUN(-alpha)
        e2 = EXP_FUN(SCALAR_VAL(-2.0) * alpha)

        k  = (SCALAR_VAL(1.0) - e1) * (SCALAR_VAL(1.0) - e1) /
             (SCALAR_VAL(1.0) + SCALAR_VAL(2.0) * alpha * e1
              - EXP_FUN(SCALAR_VAL(2.0) * alpha))

        a1 = k
        a5 = k

        a2 = k * e1 * (alpha - SCALAR_VAL(1.0))
        a6 = a2

        a3 = k * e1 * (alpha + SCALAR_VAL(1.0))
        a7 = a3

        a4 = -k * e2
        a8 = a4

        b1 = POW_FUN(SCALAR_VAL(2.0), -alpha)
        b2 = -e2

        c1 = SCALAR_VAL(1.0)
        c2 = SCALAR_VAL(1.0)

    # --------------------- Horizontal pass (x-direction) ---------------------

    HORIZ_FWD:
        # Forward IIR recursion along j (left -> right) for each row i.
        # Matches:
        #   ym1 = ym2 = xm1 = 0;
        #   for (j=0..H-1)
        #     y1[i][j] = a1*imgIn[i][j] + a2*xm1 + b1*ym1 + b2*ym2;
        #     xm1 = imgIn[i][j]; ym2 = ym1; ym1 = y1[i][j];
        for i in [0, W):
            xm1 = SCALAR_VAL(0.0)
            ym1 = SCALAR_VAL(0.0)
            ym2 = SCALAR_VAL(0.0)
            for j in seq([0, H)):
                y1[i, j] = a1 * imgIn[i, j] + a2 * xm1 + b1 * ym1 + b2 * ym2
                xm1 = imgIn[i, j]
                ym2 = ym1
                ym1 = y1[i, j]

    HORIZ_BWD:
        # Backward IIR recursion along j (right -> left) for each row i.
        # Matches:
        #   yp1 = yp2 = xp1 = xp2 = 0;
        #   for (j=H-1..0)
        #     y2[i][j] = a3*xp1 + a4*xp2 + b1*yp1 + b2*yp2;
        #     xp2 = xp1; xp1 = imgIn[i][j]; yp2 = yp1; yp1 = y2[i][j];
        for i in [0, W):
            xp1 = SCALAR_VAL(0.0)
            xp2 = SCALAR_VAL(0.0)
            yp1 = SCALAR_VAL(0.0)
            yp2 = SCALAR_VAL(0.0)
            for j_rev in seq([0, H)):
                let j = H - 1 - j_rev in
                    y2[i, j] = a3 * xp1 + a4 * xp2 + b1 * yp1 + b2 * yp2
                    xp2 = xp1
                    xp1 = imgIn[i, j]
                    yp2 = yp1
                    yp1 = y2[i, j]

    HORIZ_COMBINE:
        # Combine forward and backward responses into an intermediate imageOut.
        # Matches:
        #   imgOut[i][j] = c1 * (y1[i][j] + y2[i][j]);
        for i in [0, W), j in [0, H):
            imgOut[i, j] = c1 * (y1[i, j] + y2[i, j])

    # ---------------------- Vertical pass (y-direction) ----------------------

    VERT_FWD:
        # Forward IIR recursion along i (top -> bottom) for each column j.
        # Matches:
        #   tm1 = ym1 = ym2 = 0;
        #   for (i=0..W-1)
        #     y1[i][j] = a5*imgOut[i][j] + a6*tm1 + b1*ym1 + b2*ym2;
        #     tm1 = imgOut[i][j]; ym2 = ym1; ym1 = y1[i][j];
        for j in [0, H):
            tm1 = SCALAR_VAL(0.0)
            ym1 = SCALAR_VAL(0.0)
            ym2 = SCALAR_VAL(0.0)
            for i in seq([0, W)):
                y1[i, j] = a5 * imgOut[i, j] + a6 * tm1 + b1 * ym1 + b2 * ym2
                tm1 = imgOut[i, j]
                ym2 = ym1
                ym1 = y1[i, j]

    VERT_BWD:
        # Backward IIR recursion along i (bottom -> top) for each column j.
        # Matches:
        #   tp1 = tp2 = yp1 = yp2 = 0;
        #   for (i=W-1..0)
        #     y2[i][j] = a7*tp1 + a8*tp2 + b1*yp1 + b2*yp2;
        #     tp2 = tp1; tp1 = imgOut[i][j]; yp2 = yp1; yp1 = y2[i][j];
        for j in [0, H):
            tp1 = SCALAR_VAL(0.0)
            tp2 = SCALAR_VAL(0.0)
            yp1 = SCALAR_VAL(0.0)
            yp2 = SCALAR_VAL(0.0)
            for i_rev in seq([0, W)):
                let i = W - 1 - i_rev in
                    y2[i, j] = a7 * tp1 + a8 * tp2 + b1 * yp1 + b2 * yp2
                    tp2 = tp1
                    tp1 = imgOut[i, j]
                    yp2 = yp1
                    yp1 = y2[i, j]

    VERT_COMBINE:
        # Final combination, overwriting imgOut with the fully filtered image.
        # Matches:
        #   imgOut[i][j] = c2 * (y1[i][j] + y2[i][j]);
        for i in [0, W), j in [0, H):
            imgOut[i, j] = c2 * (y1[i, j] + y2[i, j])

dependencies:
    # Global stage ordering (no overlap between stages):
    #   COEFFS
    #   -> HORIZ_FWD -> HORIZ_BWD -> HORIZ_COMBINE
    #   -> VERT_FWD  -> VERT_BWD  -> VERT_COMBINE
    for i in [0, W):
        COEFFS()           -> HORIZ_FWD(i)
        HORIZ_FWD(i)       -> HORIZ_BWD(i)
    for i in [0, W), j in [0, H):
        HORIZ_BWD(i, j)    -> HORIZ_COMBINE(i, j)
        HORIZ_COMBINE(i, j)-> VERT_FWD(j)
        VERT_FWD(i, j)     -> VERT_BWD(j)
        VERT_BWD(i, j)     -> VERT_COMBINE(i, j)

optimization:

    # -------------------------- Parallelization ---------------------------

    # Rows are independent in horizontal passes; columns are independent in
    # vertical passes; all (i, j) are independent in the combine passes.

    parallelize(i) in HORIZ_FWD
    parallelize(i) in HORIZ_BWD

    parallelize(i) in HORIZ_COMBINE    # 2D parallel, but i is the primary split
    parallelize(j) in HORIZ_COMBINE

    parallelize(j) in VERT_FWD
    parallelize(j) in VERT_BWD

    parallelize(i) in VERT_COMBINE
    parallelize(j) in VERT_COMBINE

    # On a 32-core (64-thread) x64 machine, map parallelize(...) to an OpenMP
    # static schedule over NUM_THREADS threads with chunk sizes chosen so that
    # each thread owns several full rows/columns for good locality.

    # --------------------------- Blocking / Tiling ---------------------------

    # Block outer dimensions to improve cache reuse for large images.
    # TILE_W and TILE_H are tunable (e.g., 64–256) depending on cache sizes.

    block(i, I, TILE_W) in HORIZ_FWD
    block(i, I, TILE_W) in HORIZ_BWD
    block(i, I, TILE_W) in HORIZ_COMBINE

    block(j, J, TILE_H) in VERT_FWD
    block(j, J, TILE_H) in VERT_BWD
    block(j, J, TILE_H) in VERT_COMBINE

    # ------------------------ Coefficient hoisting --------------------------

    # All coefficient computations depend only on alpha and thus can be
    # computed once per kernel invocation, outside the image loops.

    hoist(COEFFS)

    # ------------------- Scalarization / scanline buffers -------------------

    # The mathematical model uses full 2D y1/y2 arrays, but the recurrences
    # actually need only a few previous values along the recursive dimension.
    #
    # Optimization idea:
    #   - Keep the last two outputs (ym1, ym2 / yp1, yp2) and last one or two
    #     inputs (xm1/xp1/xp2, tm1/tp1/tp2) in registers.
    #   - For horizontal passes, if we want to reduce 2D temporaries further,
    #     keep just one row of y1 in a 1D buffer; compute y2 and combine on
    #     the fly without materializing y2 as a 2D array.
    #   - Similarly for vertical passes, use a 1D column buffer for y1.
    #
    # We express this via custom directives:

    # scanline_buffer(VAR, axis, length) means:
    #   replace the 2D VAR along the given axis with a reusable 1D buffer
    #   of the indicated length, processing one row/column at a time.

    scanline_buffer(y1, axis=j, length=H) in {HORIZ_FWD, HORIZ_BWD, HORIZ_COMBINE}
    scanline_buffer(y1, axis=i, length=W) in {VERT_FWD, VERT_BWD, VERT_COMBINE}

    # After applying scanline_buffer to y1, we can fuse the backward and
    # combine passes and avoid ever storing y2 to memory:

    # fuse(A, B, axis) means:
    #   for each index along 'axis', execute A and B back-to-back on the same
    #   element, so that temporaries produced by A can be consumed by B
    #   while still in registers, eliminating extra arrays.

    fuse(HORIZ_BWD, HORIZ_COMBINE, axis=(i, j))
    fuse(VERT_BWD,  VERT_COMBINE,  axis=(i, j))

    # scalarize(VAR) means:
    #   represent VAR values only in registers across the fused region,
    #   not in a 2D array, as long as each element is used exactly once.

    scalarize(y2) in {HORIZ_BWD, HORIZ_COMBINE, VERT_BWD, VERT_COMBINE}

    # With these transformations, the implementation can reduce storage from
    # 4*W*H (imgIn, imgOut, y1, y2) down to approximately 2*W*H + O(W+H):
    #   - imgIn (input image)
    #   - imgOut (intermediate horizontal + final vertical result)
    #   - a row buffer of length H and a column buffer of length W for y1
    # which is strictly within the original memory budget.

    # -------------------------- Vectorization -------------------------------

    # The recursive inner loops (HORIZ_FWD/BWD and VERT_FWD/BWD) are
    # inherently sequential along j or i, but the combination loops are
    # purely pointwise and can be vectorized.

    vectorize(j, VF) in HORIZ_COMBINE
    vectorize(i, VF) in VERT_COMBINE

    # After applying fuse+scalarize, the combination arithmetic becomes part
    # of the backward scanline loops; compilers can still unroll those loops
    # to increase ILP. VF is typically chosen to match the hardware SIMD width.
--- END OF MODEL: deriche-03 ---

--- START OF MODEL: deriche-04 ---
# Optimized model for deriche.c

domain:
    # Image domain: width W (first index i), height H (second index j)
    i: dim in [0, W)
    j: dim in [0, H)

data:
    # 2D images stored in row-major layout: j is the contiguous index
    imgIn[i, j]:  in    DATA_TYPE = (i, j) -> i * H + j
    imgOut[i, j]: inout DATA_TYPE = (i, j) -> i * H + j
    y1[i, j]:     temp  DATA_TYPE = (i, j) -> i * H + j
    y2[i, j]:     temp  DATA_TYPE = (i, j) -> i * H + j

    # Optional 1D state buffers for cache-friendly vertical passes.
    # Size O(H), well below the 50% extra-memory budget.
    v_tm1[j]:  temp DATA_TYPE = j      # previous imgOut along column (forward)
    v_ym1[j]:  temp DATA_TYPE = j      # previous y1 along column
    v_ym2[j]:  temp DATA_TYPE = j      # y1 two steps back along column
    v_tp1[j]:  temp DATA_TYPE = j      # next imgOut along column (backward)
    v_tp2[j]:  temp DATA_TYPE = j      # imgOut two steps ahead along column
    v_yp1[j]:  temp DATA_TYPE = j      # next y2 along column
    v_yp2[j]:  temp DATA_TYPE = j      # y2 two steps ahead along column

parameters:
    alpha: DATA_TYPE

    # Filter coefficients derived from alpha; computed once per kernel call.
    k:  DATA_TYPE
    a1, a2, a3, a4, a5, a6, a7, a8: DATA_TYPE
    b1, b2, c1, c2: DATA_TYPE

    # Tuning parameters (to be chosen for the target machine).
    J_BLOCK:   int  # e.g., 64 or 128: column-tile size for vertical passes
    VEC_WIDTH: int  # SIMD width in elements, e.g., 8 for AVX2 with float

computation:
    # --- Coefficient computation (matches original math) ---
    COEFFS:
        k  = (1 - exp(-alpha)) * (1 - exp(-alpha)) /
             (1 + 2 * alpha * exp(-alpha) - exp(-2 * alpha))

        a1 = k
        a2 = k * exp(-alpha) * (alpha - 1)
        a3 = k * exp(-alpha) * (alpha + 1)
        a4 = -k * exp(-2 * alpha)

        a5 = a1
        a6 = a2
        a7 = a3
        a8 = a4

        b1 = pow(2, -alpha)
        b2 = -exp(-2 * alpha)

        c1 = 1
        c2 = 1

    # --- Horizontal 1D recursive filtering (per row) ---
    # Each row is processed independently:
    #   - forward (left->right) causal recursion into y1,
    #   - backward (right->left) anti-causal recursion into y2,
    #   - combination into horizontally filtered imgOut.

    for i in [0, W):      # rows; no inter-row dependencies
        H_FWD_INIT:
            xm1 = 0       # previous imgIn in row i
            ym1 = 0       # previous y1 in row i
            ym2 = 0       # y1 two steps back in row i

        H_FWD:
            for j in [0, H):   # j must be sequential: recurrence along j
                y1[i, j] = a1 * imgIn[i, j]
                         + a2 * xm1
                         + b1 * ym1
                         + b2 * ym2
                xm1 = imgIn[i, j]
                ym2 = ym1
                ym1 = y1[i, j]

        H_BWD_INIT:
            xp1 = 0       # imgIn[i, j+1]
            xp2 = 0       # imgIn[i, j+2]
            yp1 = 0       # y2[i, j+1]
            yp2 = 0       # y2[i, j+2]

        H_BWD:
            # Conceptually j runs H-1 .. 0 with a recurrence along j.
            for j in [0, H) in seq:   # executed in reverse index order
                j_b = H - 1 - j       # logical index from right to left
                y2[i, j_b] = a3 * xp1
                             + a4 * xp2
                             + b1 * yp1
                             + b2 * yp2
                xp2 = xp1
                xp1 = imgIn[i, j_b]
                yp2 = yp1
                yp1 = y2[i, j_b]

        H_COMBINE:
            for j in [0, H):
                imgOut[i, j] = c1 * (y1[i, j] + y2[i, j])

    # --- Vertical 1D recursive filtering on imgOut ---
    # Original code scans each column separately (strided accesses).
    # Here, we:
    #   - keep the same per-column recurrences,
    #   - but iterate row-major (i outer, j inner) and use per-column
    #     state arrays v_*[j] for better cache and vectorization.

    # Forward (top-down) vertical pass: produces new y1.
    V_FWD_STATE_INIT:
        for j in [0, H):
            v_tm1[j] = 0
            v_ym1[j] = 0
            v_ym2[j] = 0

    V_FWD:
        # For each row i, update all columns' causal recurrences.
        for i in [0, W) in seq:
            for j in [0, H):   # no dependencies across j, only across i
                y1[i, j] = a5 * imgOut[i, j]
                         + a6 * v_tm1[j]
                         + b1 * v_ym1[j]
                         + b2 * v_ym2[j]
                v_tm1[j] = imgOut[i, j]
                v_ym2[j] = v_ym1[j]
                v_ym1[j] = y1[i, j]

    # Backward (bottom-up) vertical pass, fused with final combination.
    V_BWD_STATE_INIT:
        for j in [0, H):
            v_tp1[j] = 0
            v_tp2[j] = 0
            v_yp1[j] = 0
            v_yp2[j] = 0

    V_BWD_AND_COMBINE:
        # Scan rows bottom->top to compute y2 and immediately form output.
        for i in [0, W) in seq:    # executed logically in reverse order
            i_b = W - 1 - i        # logical index from bottom to top
            for j in [0, H):
                # 1) backward recurrence for column j at row i_b
                y2[i_b, j] = a7 * v_tp1[j]
                            + a8 * v_tp2[j]
                            + b1 * v_yp1[j]
                            + b2 * v_yp2[j]

                # 2) update column state from original horizontal imgOut
                v_tp2[j] = v_tp1[j]
                v_tp1[j] = imgOut[i_b, j]

                v_yp2[j] = v_yp1[j]
                v_yp1[j] = y2[i_b, j]

                # 3) final vertical + horizontal filtered value
                imgOut[i_b, j] = c2 * (y1[i_b, j] + y2[i_b, j])

dependencies:
    # Horizontal passes:
    # - Along each row i, H_FWD and H_BWD have loop-carried dependencies
    #   along j; hence j in H_FWD and H_BWD must execute sequentially.
    # - Rows i are independent once COEFFS is computed.
    #
    # Vertical passes (restructured):
    # - For each column j, V_FWD has a dependency chain along i via
    #   v_tm1[j], v_ym1[j], v_ym2[j].
    # - Similarly, V_BWD_AND_COMBINE has a dependency chain along i
    #   via v_tp1[j], v_tp2[j], v_yp1[j], v_yp2[j].
    # - Different columns (different j) are independent.

optimization:
    # --- Horizontal passes (row-wise) ---

    # 1) Parallelize across rows: each row i has its own scalar state and
    #    disjoint slices of y1, y2, and imgOut.
    parallelize(i)  # for all horizontal loops over i

    # 2) Unroll inner j-loops in horizontal passes to improve ILP while
    #    respecting recurrences along j.
    unroll(j, 4)    # in H_FWD and H_BWD
    # 3) Vectorize the combination loop over j (no dependencies).
    vectorize(j, VEC_WIDTH)  # in H_COMBINE

    # --- Vertical passes (column-wise recurrences, row-major access) ---

    # 4) Block the column dimension j for the vertical passes and
    #    parallelize at the tile level. Each tile J owns a contiguous
    #    block of columns and uses a contiguous slice of v_* as its
    #    per-column state.
    #
    #    for J in [0, ceil(H / J_BLOCK)) in parallel:
    #        j in [J * J_BLOCK, min((J+1)*J_BLOCK, H)):
    #            # initialize v_*[j], then run V_FWD and V_BWD_AND_COMBINE
    #
    block(j, J, J_BLOCK)    # in V_FWD and V_BWD_AND_COMBINE
    hoist(J)                # make J the outermost loop in those passes
    parallelize(J)          # each J-tile processed by a separate thread

    # 5) Vectorize inner j-loops of vertical passes: after restructuring,
    #    columns are independent in j for a fixed i, so SIMD across
    #    columns is legal.
    vectorize(j, VEC_WIDTH)  # in V_FWD
    vectorize(j, VEC_WIDTH)  # in V_BWD_AND_COMBINE

    # 6) Optionally unroll the inner j-loops in the vertical passes to
    #    balance pipeline and SIMD usage.
    unroll(j, 4)  # in V_FWD and V_BWD_AND_COMBINE

    # 7) Hoist coefficient computation if alpha is reused across images:
    #    COEFFS can be executed once per alpha instead of once per image.
    hoist(COEFFS)

    # 8) Optional bandwidth optimization: if intermediate y2 values are
    #    not needed outside the kernel, V_BWD_AND_COMBINE can avoid
    #    storing y2[i, j] and use a local scalar instead, reducing one
    #    store per pixel without changing imgOut.
--- END OF MODEL: deriche-04 ---

--- START OF MODEL: deriche-05 ---
domain:
    i: dim in [0, W)      # image rows
    j: dim in [0, H)      # image columns

data:
    # 2D images, row-major (C layout: arr[i][j] -> base[i * H + j])
    imgIn[i, j]:  in    DATA_TYPE = (i, j) -> i * H + j
    tmpH[i, j]:   temp  DATA_TYPE = (i, j) -> i * H + j   # horizontally filtered image
    imgOut[i, j]: out   DATA_TYPE = (i, j) -> i * H + j   # final result

    # 1D line buffers, reused per row/column; live in L1/registers.
    # Sizes are O(W+H), so overall memory is 3 * W * H + O(W+H) < original 4 * W * H.
    y_row_fwd[j]: temp DATA_TYPE = (j) -> j              # forward horizontal response for one row
    y_row_bwd[j]: temp DATA_TYPE = (j) -> j              # backward horizontal response for one row

    colIn[i]:      temp DATA_TYPE = (i) -> i             # copy of one column of tmpH
    y_col_fwd[i]:  temp DATA_TYPE = (i) -> i             # forward vertical response for one column
    y_col_bwd[i]:  temp DATA_TYPE = (i) -> i             # backward vertical response for one column

parameters:
    alpha: DATA_TYPE        # filter parameter (same as in C code)

    # Precomputed exponentials / powers (same expressions as original C code)
    e_neg:     DATA_TYPE    # = exp(-alpha)
    e_pos2:    DATA_TYPE    # = exp( 2 * alpha)
    e_neg2:    DATA_TYPE    # = exp(-2 * alpha)
    k:         DATA_TYPE    # = (1 - e_neg)^2 / (1 + 2 * alpha * e_neg - e_pos2)

    a1: DATA_TYPE  # = k
    a2: DATA_TYPE  # = k * e_neg * (alpha - 1)
    a3: DATA_TYPE  # = k * e_neg * (alpha + 1)
    a4: DATA_TYPE  # = -k * e_neg2
    a5: DATA_TYPE  # = a1
    a6: DATA_TYPE  # = a2
    a7: DATA_TYPE  # = a3
    a8: DATA_TYPE  # = a4

    b1: DATA_TYPE  # = pow(2, -alpha)
    b2: DATA_TYPE  # = -e_neg2

    c1: DATA_TYPE  # = 1
    c2: DATA_TYPE  # = 1

    # Tunable optimization parameters
    FACTOR_I:  int  # preferred SIMD width for loops over i
    FACTOR_J:  int  # preferred SIMD width for loops over j
    FACTOR_UR: int  # unroll factor for recurrence loops

computation:
    coeffs:   # scalar coefficient setup; identical math to the C kernel
        e_neg   = EXP(-alpha)
        e_pos2  = EXP(2 * alpha)
        e_neg2  = EXP(-2 * alpha)

        k = (1 - e_neg) * (1 - e_neg) /
            (1 + 2 * alpha * e_neg - e_pos2)

        a1 = k
        a2 = k * e_neg * (alpha - 1)
        a3 = k * e_neg * (alpha + 1)
        a4 = -k * e_neg2
        a5 = a1
        a6 = a2
        a7 = a3
        a8 = a4

        b1 = POW(2, -alpha)
        b2 = -e_neg2

        c1 = 1
        c2 = 1

    # ----------------------------------------------------------------------
    # Horizontal filtering: for each row, apply 1D Deriche (causal + anti-causal)
    # along j on imgIn, then combine into tmpH.
    # This fuses the first three loops of the original code and replaces 2D y1,y2
    # by row-local 1D buffers.
    # ----------------------------------------------------------------------
    H_rows:
        for i in [0, W) parallel:     # each row is independent

            H_fwd:   # causal (left-to-right) horizontal pass
                for j in seq([0, H)):
                    y_row_fwd[j] =
                          a1 * imgIn[i, j]
                        + a2 * (if j > 0   then imgIn[i, j-1]    else 0)
                        + b1 * (if j > 0   then y_row_fwd[j-1]   else 0)
                        + b2 * (if j > 1   then y_row_fwd[j-2]   else 0)

            H_bwd:   # anti-causal (right-to-left) horizontal pass
                # Executed in decreasing j to match the original dependency direction.
                for j in seq([H-1, -1]):   # j = H-1, H-2, ..., 0
                    y_row_bwd[j] =
                          a3 * (if j < H-1 then imgIn[i, j+1]    else 0)
                        + a4 * (if j < H-2 then imgIn[i, j+2]    else 0)
                        + b1 * (if j < H-1 then y_row_bwd[j+1]   else 0)
                        + b2 * (if j < H-2 then y_row_bwd[j+2]   else 0)

            H_combine:  # combine horizontal causal & anti-causal contributions
                for j in [0, H):
                    tmpH[i, j] = c1 * (y_row_fwd[j] + y_row_bwd[j])

    # At this point tmpH == imgOut after the first combination in the original C code.

    # ----------------------------------------------------------------------
    # Vertical filtering: for each column, copy it into a contiguous buffer,
    # apply 1D Deriche (causal + anti-causal) along i, then write imgOut.
    #
    # Compared to the original:
    #   - imgOut from the horizontal stage is called tmpH here.
    #   - We read each tmpH[i, j] only once by using colIn.
    #   - Vertical recurrences run over contiguous 1D buffers (better cache/SIMD).
    # ----------------------------------------------------------------------
    V_cols:
        for j in [0, H) parallel:   # each column is independent

            copy_column:
                for i in [0, W):
